const e="Registration and Taking Courses",t={verified:!1,lastEdited:"9/6/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/undergraduate/academic-policies-procedures/registration-taking-courses/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"major",score:.68,checkedAt:"2026-09-07",sourceUrl:"https://catalog.northeastern.edu/undergraduate/academic-policies-procedures/registration-taking-courses/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:3,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"no-sample-plan",severity:"medium",message:"this program publishes no sample four-year plan, so our strongest check could not run",detail:[{key:"noPlanUnusual"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"3 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"Reduced Load Policies",sh:12}},{key:"unenumeratedSection",params:{title:"Audit Policy",sh:16}},{key:"unenumeratedSection",params:{title:"Taking Courses While on Co-op",sh:4}}],overflow:0}]}},o=0,r=2027,a=[{type:"SECTION",title:"Reduced Load Policies",creditsRequired:12,minRequirementCount:1,requirements:[],notes:["Undergraduate full-time students are generally expected to take a full-time course load in progression toward their degree. Tuition adjustments for reduced loads are made only when the Undergraduate Petition to Reduce Load is approved by the academic advisor. Tuition adjustments are made for approved reduced course loads if the registered credits fall below 12 semester hours (calculated at the per-credit-hour rate). To receive petition for the adjustment, the Undergraduate Petition to Reduce Load must be submitted prior to the start of the term. Please refer to SFS Billing Policies for further information.","No rebate or credit is granted when a student voluntarily drops a course. A reduced load may impact the student’s housing, degree progress, financial aid, visa status, and health insurance. Students should consult applicable departments before committing to a reduced load. Students who take a reduced load will be billed at the per-credit-hour rate, 1/16th of the full-semester tuition for that semester per semester hour.","International students must speak with an advisor at the Office of Global Services prior to dropping a course. Permission to drop below full-time status is restricted according to federal regulations."]},{type:"SECTION",title:"Audit Policy",creditsRequired:16,minRequirementCount:1,requirements:[],notes:["Full-time Northeastern students may audit one class per term as an overload above 16 semester hours with no additional charge."]},{type:"SECTION",title:"Taking Courses While on Co-op",creditsRequired:4,minRequirementCount:1,requirements:[],notes:["Students who wish to take more than 4 semester hours while on full-time co-op must complete the petition registration form with their college academic advising office before the term begins. Students who do not receive the approval of their academic advisor and co-op coordinator will be dropped from their preregistered courses. Students who take a course while on co-op will be billed the per-credit-hour tuition rate. (See “Reduced Load Policies” above.)"]}],i={name:e,metadata:t,totalCreditsRequired:o,yearVersion:r,requirementSections:a};export{i as default,t as metadata,e as name,a as requirementSections,o as totalCreditsRequired,r as yearVersion};
